insert into public.preparations (herb_id, method, title, instructions, note, sort_order) values ((select id from public.herbs where slug = 'muscade'), 'cuisine', 'Râpée au dernier moment', 'Râpez la noix fraîche sur les béchamels, purées, gratins et desserts ; le parfum est bien plus riche que la poudre.', null, 0);
