insert into public.precautions (herb_id, kind, severity, description) values ((select id from public.herbs where slug = 'muscade'), 'precaution', 'attention', 'Grossesse : éviter les usages médicinaux ; l''usage culinaire reste possible.');
insert into public.herbs (slug, common_name, scientific_name, family, summary, parts_used, active_principles, harvest_months, published) values ('poivre-noir', 'Poivre noir', 'Piper nigrum', 'Pipéracées', 'Baies du poivrier grimpant, l''épice reine, à la morsure piquante et fruitée.', array['Baies (noir, blanc, vert)']::text[], array['Pipérine','Huile essentielle']::text[], array[2,3,4]::int[], true) on conflict (slug) do nothing;
