insert into public.preparations (herb_id, method, title, instructions, note, sort_order) values ((select id from public.herbs where slug = 'poivre-noir'), 'cuisine', 'Moulu au dernier moment', 'Le poivre perd son parfum en poudre : moulez-le juste avant de servir.', null, 0);
