insert into public.precautions (herb_id, kind, severity, description) values ((select id from public.herbs where slug = 'poivre-noir'), 'effet-indesirable', 'attention', 'À forte dose, il peut irriter les muqueuses (estomac, gorge). L''usage culinaire habituel est sans souci.');
insert into public.herbs (slug, common_name, scientific_name, family, summary, parts_used, active_principles, harvest_months, published) values ('nigelle', 'Nigelle', 'Nigella sativa', 'Renonculacées', 'Petites graines noir bleuté, appelées « cumin noir », au goût poivré-fruité unique.', array['Graines','Huile de graines']::text[], array['Thymoquinone','Huile grasse']::text[], array[7,8]::int[], true) on conflict (slug) do nothing;
