insert into public.benefits (herb_id, symptom_id, description, evidence_level) values ((select id from public.herbs where slug = 'nigelle'), (select id from public.symptoms where slug = 'voies-respiratoires'), 'Des études explorent l''huile de nigelle sur les inconforts respiratoires saisonniers ; les résultats restent préliminaires.', 'etudes') on conflict do nothing;
insert into public.preparations (herb_id, method, title, instructions, note, sort_order) values ((select id from public.herbs where slug = 'nigelle'), 'cuisine', 'Graines sur le pain', 'Graines telles quelles sur les pains, focaccias et fromages ; légèrement torréfiées pour libérer l''arôme.', null, 0);
