insert into public.precautions (herb_id, kind, severity, description) values ((select id from public.herbs where slug = 'nigelle'), 'precaution', 'attention', 'Grossesse : évitez les usages médicinaux ; l''usage culinaire reste possible.');
insert into public.precautions (herb_id, kind, severity, description) values ((select id from public.herbs where slug = 'nigelle'), 'effet-indesirable', 'attention', 'Allergie possible (Renonculacées) ; commencez par de petites quantités.');
insert into public.herbs (slug, common_name, scientific_name, family, summary, parts_used, active_principles, harvest_months, published) values ('badiane', 'Badiane', 'Illicium verum', 'Schisandracées', 'Étoiles ligneuses de l''anis chinois, au parfum puissant et sucré, emblème du vin chaud et du pho.', array['Fruits (étoiles)']::text[], array['Anéthol','Huile essentielle']::text[], array[10,11]::int[], true) on conflict (slug) do nothing;
