insert into public.benefits (herb_id, symptom_id, description, evidence_level) values ((select id from public.herbs where slug = 'badiane'), (select id from public.symptoms where slug = 'voies-respiratoires'), 'Utilisée traditionnellement en tisane douce lors des refroidissements.', 'traditionnel') on conflict do nothing;
insert into public.preparations (herb_id, method, title, instructions, note, sort_order) values ((select id from public.herbs where slug = 'badiane'), 'infusion', 'Tisane d''étoile', '1 étoile écrasée pour 200 ml d''eau frémissante, 10 minutes. Délicieuse avec du miel et une rondelle de citron.', null, 0);
