insert into public.precautions (herb_id, kind, severity, description) values ((select id from public.herbs where slug = 'badiane'), 'precaution', 'danger', 'Ne pas confondre avec la badiane du Japon (Illicium anisatum), toxique (anisatine) : achetez la badiane uniquement auprès de sources fiables (épicerie fine, pharmacie), jamais en cueillette.');
insert into public.herbs (slug, common_name, scientific_name, family, summary, parts_used, active_principles, harvest_months, published) values ('angelique', 'Angélique', 'Angelica archangelica', 'Apiacées', 'Grande ombellifère des montagnes, tout se mange : tiges confites, feuilles en tisane, racine en décoction.', array['Feuilles','Tiges','Racine','Graines']::text[], array['Huile essentielle','Furocoumarines','Tanins']::text[], array[8,9,10]::int[], true) on conflict (slug) do nothing;
