insert into public.precautions (herb_id, kind, severity, description) values ((select id from public.herbs where slug = 'passiflore'), 'effet-indesirable', 'attention', 'Peut provoquer une somnolence : prudence au volant après une tisane du soir.');
insert into public.precautions (herb_id, kind, severity, description) values ((select id from public.herbs where slug = 'passiflore'), 'precaution', 'attention', 'Grossesse et allaitement : demandez l''avis de votre médecin ou sage-femme avant tout usage.');
insert into public.herbs (slug, common_name, scientific_name, family, summary, parts_used, active_principles, harvest_months, published) values ('millepertuis', 'Millepertuis', 'Hypericum perforatum', 'Hypericacées', 'Sommités fleuries jaunes percées de points lumineux, traditionnellement liées au moral — mais la plante aux interactions les plus redoutées.', array['Sommités fleuries']::text[], array['Hypéricine','Hyperforine','Flavonoïdes']::text[], array[6,7,8]::int[], true) on conflict (slug) do nothing;
insert into public.benefits (herb_id, symptom_id, description, evidence_level) values ((select id from public.herbs where slug = 'millepertuis'), (select id from public.symptoms where slug = 'stress-sommeil'), 'Selon monographie, traditionnellement utilisée pour soutenir l''humeur et le bien-être émotionnel.', 'monographie') on conflict do nothing;
insert into public.preparations (herb_id, method, title, instructions, note, sort_order) values ((select id from public.herbs where slug = 'millepertuis'), 'maceration', 'Huile de millepertuis', 'Fleurs fraîches macérées dans de l''huile d''olive 3 semaines au soleil (l''huile devient rouge) ; usage externe, en application locale.', 'L''usage interne concentré (extraits) se fait sur avis médical uniquement.', 0);
insert into public.precautions (herb_id, kind, severity, description) values ((select id from public.herbs where slug = 'millepertuis'), 'interaction', 'danger', 'Interactions médicamenteuses majeures (pilule contraceptive, anticoagulants, antidépresseurs, immunosuppresseurs, etc.) : ne consommez JAMAIS le millepertuis en usage interne sans avis médical, et signalez-le à votre médecin ou pharmacien.');
insert into public.precautions (herb_id, kind, severity, description) values ((select id from public.herbs where slug = 'millepertuis'), 'effet-indesirable', 'attention', 'Photosensibilisation : la peau peut réagir au soleil après un usage régulier ; évitez l''exposition intense.');
insert into public.herbs (slug, common_name, scientific_name, family, summary, parts_used, active_principles, harvest_months, published) values ('reine-des-pres', 'Reine-des-prés', 'Filipendula ulmaria', 'Rosacées', 'Catacles crémeux et miellés des fossés d''été, contenant naturellement des dérivés salicylés (dont vient l''aspirine).', array['Sommités fleuries','Feuilles']::text[], array['Dérivés salicylés','Flavonoïdes','Tanins']::text[], array[6,7,8]::int[], true) on conflict (slug) do nothing;
insert into public.benefits (herb_id, symptom_id, description, evidence_level) values ((select id from public.herbs where slug = 'reine-des-pres'), (select id from public.symptoms where slug = 'confort-urinaire'), 'Traditionnellement employée en tisane douce lors des cures de confort urinaire et d''élimination rénale.', 'traditionnel') on conflict do nothing;
insert into public.preparations (herb_id, method, title, instructions, note, sort_order) values ((select id from public.herbs where slug = 'reine-des-pres'), 'infusion', 'Tisane de fleurs', '1 cuillère à café de sommités fleuries séchées pour 150 ml d''eau chaude, 10 minutes, filtrer.', null, 0);
insert into public.precautions (herb_id, kind, severity, description) values ((select id from public.herbs where slug = 'reine-des-pres'), 'contre-indication', 'danger', 'Allergie à l''aspirine (intolérance aux salicylés), asthme aspirinique : à éviter impérativement.');
insert into public.precautions (herb_id, kind, severity, description) values ((select id from public.herbs where slug = 'reine-des-pres'), 'precaution', 'attention', 'Traitement anticoagulant : demandez un avis médical avant un usage régulier.');
insert into public.tips (slug, category, title, body) values ('menthe-en-pot', 'culture', 'Cultiver la menthe en pot', 'La menthe est envahissante : plantez-la dans un pot ou un seau enterré. Sol frais, mi-ombre, arrosage régulier. Taillez souvent pour garder un feuillage tendre.') on conflict (slug) do nothing;
insert into public.tips (slug, category, title, body) values ('thym-soleil', 'culture', 'Un thym heureux : soleil et drainage', 'Plein soleil, sol pauvre et très drainant, peu d''eau. Taillez légèrement après la floraison pour éviter qu''il ne se dégarnisse.') on conflict (slug) do nothing;
insert into public.tips (slug, category, title, body) values ('basilic-chaleur', 'culture', 'Réussir son basilic', 'Semez après les derniers gels, au chaud et en plein soleil. Pincez les têtes pour le faire ramifier et retirez les boutons floraux pour prolonger la récolte.') on conflict (slug) do nothing;
insert into public.tips (slug, category, title, body) values ('persil-germination', 'culture', 'Faire germer le persil', 'Sa germination est lente (3 à 6 semaines). Semez en place dans un sol frais, car il supporte mal la transplantation.') on conflict (slug) do nothing;
insert into public.tips (slug, category, title, body) values ('romarin-hiver', 'culture', 'Romarin : sec et ensoleillé', 'Il craint l''excès d''eau plus que le froid. Offrez-lui un sol drainant ; en pot, évitez la soucoupe pleine en hiver.') on conflict (slug) do nothing;
insert into public.tips (slug, category, title, body) values ('secher-herbes', 'conservation', 'Sécher ses herbes', 'Récoltez le matin après la rosée, puis suspendez-les en petits bouquets, à l''ombre dans un endroit aéré. Conservez-les dans des bocaux opaques, loin de la chaleur et de l''humidité.') on conflict (slug) do nothing;
insert into public.tips (slug, category, title, body) values ('glacons-herbes', 'conservation', 'Congeler en glaçons', 'Hachez des herbes tendres (menthe, mélisse, persil, ciboulette), répartissez-les dans un bac à glaçons, couvrez d''eau ou d''huile d''olive et congelez.') on conflict (slug) do nothing;
insert into public.tips (slug, category, title, body) values ('tiges-eau', 'conservation', 'Garder les herbes fraîches au frigo', 'Les herbes tendres (persil, coriandre, menthe) tiennent plus longtemps debout dans un verre d''eau, au frais. Le basilic, lui, déteste le froid : gardez-le à température ambiante.') on conflict (slug) do nothing;
insert into public.tips (slug, category, title, body) values ('labelliser', 'conservation', 'Étiqueter et dater', 'Notez le nom et la date de séchage sur chaque bocal. Les herbes séchées gardent leurs arômes environ un an ; au-delà, renouvelez-les.') on conflict (slug) do nothing;
insert into public.tips (slug, category, title, body) values ('infusion-couvrir', 'quotidien', 'Une infusion réussie', 'Couvrez la tasse pendant l''infusion pour garder les huiles volatiles, et utilisez une eau frémissante plutôt que bouillante pour les feuilles tendres.') on conflict (slug) do nothing;
insert into public.tips (slug, category, title, body) values ('fraiches-ou-seches', 'quotidien', 'Fraîches ou sèches ?', 'Les herbes robustes (thym, romarin, laurier, origan) s''ajoutent en début de cuisson. Les herbes tendres (basilic, persil, ciboulette, cerfeuil) se glissent à la fin.') on conflict (slug) do nothing;
insert into public.tips (slug, category, title, body) values ('pas-de-cueillette-sauvage', 'quotidien', 'Cueillette sauvage : prudence', 'Certaines plantes toxiques ressemblent à des herbes comestibles (ciguë et cerfeuil, laurier-rose et laurier-sauce). N''utilisez que des plantes identifiées avec certitude.') on conflict (slug) do nothing;
insert into public.tips (slug, category, title, body) values ('avis-pro', 'quotidien', 'Quand demander conseil', 'Grossesse, allaitement, enfants, traitement en cours ou maladie chronique : parlez-en à votre médecin ou à votre pharmacien avant tout usage médicinal régulier.') on conflict (slug) do nothing;
